#include <iostream>
#include <vector>
struct T {
    T() = default;
    T(const T&) { std::cout << "C"; }
    T(T&&) { std::cout << "M"; }
};
int main() {
    std::vector<T> v;
    v.reserve(1);
    v.emplace_back();
    v.emplace_back();  // grows: the old element is transferred
    std::cout << "\n";
}
